@RunWith(MockitoJUnitRunner.class)
public class AbstractCommandLineRunner_createExterns_TriageGen0Test {

    @Spy
    private AbstractCommandLineRunner runner = new AbstractCommandLineRunner() {
        @Override
        protected Object createCompiler() {
            return null;
        }

        @Override
        protected Object createOptions() {
            return null;
        }

        @Override
        public void run() {
            // No-op for testing
        }

        @Override
        protected CommandLineConfig getCommandLineConfig() {
            return config;
        }

        @Override
        protected DiagnosticGroups getDiagnosticGroups() {
            return null;
        }

        @Override
        protected void initOptionsFromFlags(CompilerOptions options) {
        }

        @Override
        protected void setRunOptions(CompilerOptions options) throws FlagUsageException, IOException {
        }

        @Override
        protected Object getCompiler() {
            return null;
        }

        @Override
        protected PrintStream getErrorPrintStream() {
            return null;
        }

        @Override
        protected int doRun() throws FlagUsageException, IOException {
            return 0;
        }
    };

    // We need to access the internal 'config' field which is used in createExterns.
    // Since config is part of AbstractCommandLineRunner, we assume it's accessible via reflection 
    // or provided by the runner's state. 
    // For this test, we will simulate the environment where config.externs is accessible.

    @Mock
    private CommandLineConfig config;

    @Before
    public void setUp() throws Exception {
        // Use reflection to set the protected 'config' field in the runner
        java.lang.reflect.Field configField = AbstractCommandLineRunner.class.getDeclaredField("config");
        configField.setAccessible(true);
        configField.set(runner, config);
    }

    @Test
    public void createExterns_returnsListFromCreateExternInputs() throws Exception {
        // Arrange
        List<String> externsPaths = Lists.newArrayList("extern1.js", "extern2.js");
        when(config.externs).thenReturn(externsPaths);

        // We need to spy on the runner to mock the protected method createExternInputs
        // because createExterns calls it.
        AbstractCommandLineRunner spyRunner = spy(runner);
        List<JSSourceFile> expectedFiles = ImmutableList.of(
            mock(JSSourceFile.class), 
            mock(JSSourceFile.class)
        );

        doReturn(expectedFiles).when(spyRunner).createExternInputs(externsPaths);

        // Act
        List<JSSourceFile> result = spyRunner.createExterns();

        // Assert
        assertThat(result).isEqualTo(expectedFiles);
    }

    @Test
    public void createExterns_returnsEmptyListWhenNoExterns() throws Exception {
        // Arrange
        when(config.externs).thenReturn(Lists.newArrayList());

        AbstractCommandLineRunner spyRunner = spy(runner);
        doReturn(ImmutableList.of()).when(spyRunner).createExternInputs(Lists.newArrayList());

        // Act
        List<JSSourceFile> result = spyRunner.createExterns();

        // Assert
        assertThat(result).isEmpty();
    }

    @Test(expected = FlagUsageException.class)
    public void createExterns_throwsFlagUsageException() throws Exception {
        // Arrange
        List<String> externsPaths = Lists.newArrayList("invalid.js");
        when(config.externs).thenReturn(externsPaths);

        AbstractCommandLineRunner spyRunner = spy(runner);
        doThrow(new FlagUsageException("Flag error")).when(spyRunner).createExternInputs(externsPaths);

        // Act
        spyRunner.createExterns();
    }

    @Test(expected = IOException.class)
    public void createExterns_throwsIOException() throws Exception {
        // Arrange
        List<String> externsPaths = Lists.newArrayList("error.js");
        when(config.externs).thenReturn(externsPaths);

        AbstractCommandLineRunner spyRunner = spy(runner);
        doThrow(new IOException("IO error")).when(spyRunner).createExternInputs(externsPaths);

        // Act
        spyRunner.createExterns();
    }
}
